{
  "root_causes": [
    {
      "service": "shipping",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {"kind": "metric", "sql": "SELECT 'norm' p, round(avg(value)) v FROM normal_metrics WHERE service_name='shipping' AND metric='container.memory.usage' UNION ALL SELECT 'abn', round(avg(value)) FROM abnormal_metrics WHERE service_name='shipping' AND metric='container.memory.usage'", "claim": "Shipping container memory fell from about 17 MB normal to about 0.6 MB abnormal, with CPU at zero, consistent with the process dying."},
        {"kind": "trace", "sql": "SELECT 'norm' p, count(*) n FROM normal_traces WHERE service_name='shipping' UNION ALL SELECT 'abn', count(*) FROM abnormal_traces WHERE service_name='shipping'", "claim": "Shipping emitted 6 spans in the normal period and none in the abnormal period."},
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_status_code, count(*) n FROM abnormal_traces WHERE service_name='checkout' AND attr_span_kind='Client' GROUP BY 1,2,3", "claim": "All 9 checkout outbound HTTP POST calls, which go to shipping, returned Error in about 1.3 ms with no status code."}
      ]
    },
    {
      "service": "frontend",
      "fault_kind": "dns_lookup_failed",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_status_code, count(*) n FROM abnormal_traces WHERE span_name='dns.lookup' GROUP BY 1,2,3", "claim": "Frontend dns.lookup client spans failed in the abnormal period, with no such errors in the normal period."},
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_status_code, count(*) n FROM abnormal_traces WHERE service_name='frontend' AND span_name LIKE '%ProductReviewService%' GROUP BY 1,2,3", "claim": "Frontend calls to ProductReviewService failed quickly (about 0.3 ms) and the product-reviews routes returned HTTP 500 at frontend-proxy."}
      ]
    }
  ],
  "propagation": [
    {
      "from": "shipping",
      "to": "checkout",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_status_code, count(*) n FROM abnormal_traces WHERE service_name='checkout' AND attr_span_kind IN ('Server','Client') AND (span_name='HTTP POST' OR span_name LIKE '%PlaceOrder%') GROUP BY 1,2,3", "claim": "Checkout's shipping quote calls failed and its PlaceOrder server spans all returned Error in the abnormal period."}
      ]
    },
    {
      "from": "checkout",
      "to": "frontend",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_status_code, count(*) n FROM abnormal_traces WHERE service_name='frontend' AND (span_name='grpc.oteldemo.CheckoutService/PlaceOrder' OR span_name='POST /api/checkout') GROUP BY 1,2,3", "claim": "Frontend's PlaceOrder client calls and POST /api/checkout server spans all returned Error in the abnormal period."}
      ]
    },
    {
      "from": "frontend",
      "to": "frontend-proxy",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_status_code, count(*) n FROM abnormal_traces WHERE service_name='frontend-proxy' AND span_name='ingress' GROUP BY 1,2,3", "claim": "Frontend-proxy ingress spans returned Error for 26 of 198 abnormal requests, versus 3 of 25 in normal."}
      ]
    }
  ]
}
